import * as T from './vendor/three.module.js';
import {loadStudioModel,releaseModel} from './studio-models.js';
export function createWearableModels(body,head,{conceptRoot=null,onChange=()=>{}}={}){
 const entries=new Map();let sleeping=false,hatHidden=false;
 const signal=(o,state,message)=>{document.dispatchEvent(new CustomEvent('studio-model-state',{detail:{id:o.id,state,message}}));onChange(o,state,message)};
 function paint(e){const o=e.spec,m=e.model,s=m.userData.size,concept=o.slot==='garment';const parent=concept?conceptRoot:o.slot==='hat'?head:o.slot==='wrist'?body.getObjectByName('arm-0'):body;if(!parent)return;parent.add(m);if(o.slot==='hat'){const scale=o.width/s.x;m.scale.setScalar(scale);}else m.scale.set(o.width/s.x,o.height/s.y,o.depth/s.z);m.position.set(concept?0:o.x,concept?.15:o.y-(o.slot==='hat'?(m.userData.hatBase||0)*m.scale.y:0),concept?0:o.z);m.rotation.y=o.yaw;m.visible=!sleeping&&!(o.slot==='hat'&&hatHidden);m.traverse(x=>{if(x.isMesh)for(const mat of(Array.isArray(x.material)?x.material:[x.material]))if(mat.color)mat.color.copy(mat.userData.baseColor).multiply(new T.Color(o.tint))});}
 function sync(items=[]){const desired=items.filter(o=>o.slot!=='garment'||conceptRoot),ids=new Set(desired.map(o=>o.id));for(const [id,e]of entries)if(!ids.has(id)){e.abort.abort();if(e.model)releaseModel(e.model);entries.delete(id)}for(const o of desired){let e=entries.get(o.id);if(e&&e.asset!==o.asset){e.abort.abort();if(e.model)releaseModel(e.model);entries.delete(o.id);e=null}if(!e){e={asset:o.asset,spec:o,abort:new AbortController()};entries.set(o.id,e);signal(o,'loading');loadStudioModel(o.asset,e.abort.signal).then(m=>{if(entries.get(o.id)!==e){releaseModel(m);return}e.model=m;paint(e);signal(o,'ready')}).catch(err=>{if(!e.abort.signal.aborted){e.failed=true;signal(o,'failed',err.message)}})}e.spec=o;if(e.model)paint(e)}}
 function retry(){const specs=[...entries.values()].map(e=>e.spec);for(const [id,e]of entries)if(e.failed){e.abort.abort();entries.delete(id)}sync(specs)}
 globalThis.document?.addEventListener?.('studio-retry-model',retry);
 return {sync,sleep(v){sleeping=!!v;entries.forEach(e=>{if(e.model)paint(e)})},hideHat(v){hatHidden=!!v;entries.forEach(e=>{if(e.model)paint(e)})},dispose(){globalThis.document?.removeEventListener?.('studio-retry-model',retry);for(const e of entries.values()){e.abort.abort();if(e.model)releaseModel(e.model)}entries.clear()}};
}
